Plot

Prepare Data

breaks &lt;- c(-Inf, 0, 3, 5, 10, 15, Inf)


# fmt: skip
category_labels &lt;- c(
  "0", "1 - 3", "4 - 5", "6 - 10", "11 - 15", "Above 15"
)


fill_scale &lt;- brewer.pal(6, "PuRd") |&gt; rev()


category_cut &lt;- function(x) {
  x |&gt;
    cut(
      breaks = breaks,
      labels = category_labels,
      include.lowest = TRUE,
      right = TRUE
    ) |&gt;
    factor(
      ordered = TRUE,
      levels = category_labels
    )
}


plot_data &lt;-
  data |&gt;
  mutate(
    category = 0:19 |&gt;
      sample(
        size = n(),
        replace = TRUE,
        prob = seq(20, 1)
      ) |&gt;
      category_cut(),
    color = category |&gt;
      as.character() |&gt;
      recode_values(
        from = category |&gt; levels(),
        to = fill_scale
      )
  )


